[
  {
    "statement": "There is no research specifically evaluating the use of genetic modification to make crops unpalatable to primates as a conservation strategy.",
    "citations": []
  },
  {
    "statement": "The conservation evidence base contains no studies that have directly tested genetically modifying crops to reduce primate crop raiding.",
    "citations": []
  },
  {
    "statement": "Related non-genetically modified organism approaches have been explored.",
    "citations": [
      "1439",
      "1438"
    ]
  },
  {
    "statement": "Changing to crops less palatable to primates has not been studied for effectiveness.",
    "citations": [
      "1439"
    ]
  },
  {
    "statement": "Using unpalatable buffer crops lacks evidence for its effects on primate populations.",
    "citations": [
      "1438"
    ]
  },
  {
    "statement": "One genetic modification study examined genetically modified organism crops that produce pesticide to replace conventional pesticides.",
    "citations": [
      "3895"
    ]
  },
  {
    "statement": "The study on genetically modified crops producing pesticide focused on butterflies and moths rather than primates.",
    "citations": [
      "3895"
    ]
  },
  {
    "statement": "The study on genetically modified crops producing pesticide found no negative effects on caterpillar survival or growth.",
    "citations": [
      "3895"
    ]
  },
  {
    "statement": "Alternative deterrent methods show mixed results.",
    "citations": [
      "2492"
    ]
  },
  {
    "statement": "Chili-based deterrents repelled elephants in five of seven studies.",
    "citations": [
      "2492"
    ]
  },
  {
    "statement": "The species-specific evidence regarding chili-based deterrents on elephants may not translate to primate deterrence.",
    "citations": [
      "2492"
    ]
  },
  {
    "statement": "Systematic searches found no quantitative studies assessing crop palatability modification strategies for primate conservation.",
    "citations": []
  }
]
